package br.com.cineo;
import android.app.*;import android.content.*;import android.content.pm.ActivityInfo;import android.net.*;import android.os.SystemClock;import android.widget.*;import org.json.*;import java.util.*;
/** Viewer-scoped preferences, optional breaks and one quality sample per playback session. */
class PlaybackExperience {
 final MainActivity a;long started,playingSince,played,lastTick,bufferAt,stalled;int startup,stalls;String sample="";boolean ready=false,wasWifi=false,networkWarned=false,breakShown=false;long marathonStarted,marathonPlayed;String account="";
 PlaybackExperience(MainActivity activity){a=activity;}
 boolean wifi(){ConnectivityManager manager=(ConnectivityManager)a.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities capabilities=manager.getNetworkCapabilities(manager.getActiveNetwork());return capabilities!=null&&capabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI);}
 void setup(){started=SystemClock.elapsedRealtime();lastTick=started;stalls=0;stalled=0;bufferAt=0;startup=0;ready=false;sample=UUID.randomUUID().toString();wasWifi=wifi();networkWarned=false;if(!account.equals(a.local("viewer"))){account=a.local("viewer");marathonStarted=0;marathonPlayed=0;}if(marathonStarted==0)marathonStarted=started;breakShown=false;applyOrientation();if(a.drama.publicEpisode()){a.socialRequest("GET","/v8/preferences",null,r->{a.libraryHub.applySettings(r);applyOrientation();});int position=a.prefs.getInt(a.local("episode_"+a.playingEpisode),0);if(position>5000)a.socialRequest("GET","/v8/episode/"+a.playingEpisode+"/recap",null,r->{String text=r.optString("recap");if(!text.isEmpty()){a.video.pause();new AlertDialog.Builder(a).setTitle("Antes de continuar").setMessage(text).setPositiveButton("Continuar assistindo",(d,n)->{if(a.video!=null)a.video.start();}).setOnCancelListener(d->{if(a.video!=null)a.video.start();}).show();}});}}
 void applyOrientation(){String preference=a.prefs.getString(a.local("orientation"),"auto");a.setRequestedOrientation(preference.equals("portrait")?ActivityInfo.SCREEN_ORIENTATION_SENSOR_PORTRAIT:preference.equals("landscape")?ActivityInfo.SCREEN_ORIENTATION_SENSOR_LANDSCAPE:ActivityInfo.SCREEN_ORIENTATION_UNSPECIFIED);}
 void prepared(){ready=true;startup=(int)Math.min(300000,SystemClock.elapsedRealtime()-started);}
 void buffered(int code){long now=SystemClock.elapsedRealtime();if(code==701&&bufferAt==0){stalls++;bufferAt=now;}if(code==702&&bufferAt>0){stalled+=now-bufferAt;bufferAt=0;}}
 void tick(){if(a.video==null)return;long now=SystemClock.elapsedRealtime();if(a.video.isPlaying()){long delta=Math.max(0,Math.min(1000,now-lastTick));played+=delta;marathonPlayed+=delta;}lastTick=now;int minutes=a.prefs.getInt(a.local("watch_minutes"),0);if(minutes>0&&!breakShown&&marathonPlayed>=minutes*60000L){breakShown=true;a.video.pause();new AlertDialog.Builder(a).setTitle("Hora de uma pausa?").setMessage("Seu lembrete de "+minutes+" minutos chegou.").setPositiveButton("Continuar",(d,n)->{marathonStarted=SystemClock.elapsedRealtime();marathonPlayed=0;breakShown=false;if(a.video!=null)a.video.start();}).setNegativeButton("Fazer uma pausa",(d,n)->a.loadDetail(a.activeShow.optInt("id"),a.activeOrigin)).show();}if(wasWifi&&!networkWarned&&now%3000<500){boolean connected=wifi();ConnectivityManager manager=(ConnectivityManager)a.getSystemService(Context.CONNECTIVITY_SERVICE);NetworkCapabilities capabilities=manager.getNetworkCapabilities(manager.getActiveNetwork());if(!connected&&capabilities!=null&&capabilities.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR)){networkWarned=true;boolean playing=a.video.isPlaying();a.video.pause();new AlertDialog.Builder(a).setTitle("Sua conexão mudou").setMessage("O Wi-Fi foi desconectado. Continuar usa os dados móveis do seu plano.").setPositiveButton("Continuar com dados",(d,n)->{if(playing&&a.video!=null)a.video.start();}).setNegativeButton("Parar por enquanto",(d,n)->a.loadDetail(a.activeShow.optInt("id"),a.activeOrigin)).setCancelable(false).show();}}}
 void release(){if(!ready||a.video==null||!a.drama.publicEpisode()||a.token.isEmpty())return;ready=false;final String bearer=a.token,viewer=a.viewerToken;final int episode=a.playingEpisode;final String id=sample;final int initial=startup,count=Math.min(1000,stalls);final long ms=Math.min(14400000,stalled+(bufferAt>0?SystemClock.elapsedRealtime()-bufferAt:0));a.io.execute(()->{try{a.requestViewer.set(viewer);a.request("POST","/v8/quality",a.obj("id",id,"episode_id",episode,"startup_ms",initial,"stall_count",count,"stall_ms",ms),bearer);}catch(Exception ignored){}finally{a.requestViewer.remove();}});}
 void options(){new AlertDialog.Builder(a).setTitle("Mais opções").setItems(new String[]{"Reprodução e imagem","Legendas e áudio","Salvar cena","Compartilhar ou denunciar","Tempo e preferências","Conexões e downloads"},(dialog,n)->{if(n==0)a.drama.originalMore();if(n==1)new AlertDialog.Builder(a).setTitle("Legendas e áudio").setItems(new String[]{"Idiomas e audiodescrição","Aparência das legendas","Ativar / desativar legenda"},(d,i)->{if(i==0)a.playerExtras.tracks();if(i==1)a.playerExtras.subtitleStyle();if(i==2){a.pro.subtitlesOn=!a.pro.subtitlesOn;a.prefs.edit().putBoolean(a.local("subtitles_on"),a.pro.subtitlesOn).apply();}}).show();if(n==2)a.libraryHub.saveScene();if(n==3)new AlertDialog.Builder(a).setTitle("Este episódio").setItems(new String[]{"Compartilhar","Denunciar"},(d,i)->{if(i==0)a.pro.share(a.activeShow,a.playingEpisode);else if(a.drama.publicEpisode())a.pro.report("episode",a.playingEpisode);}).show();if(n==4)new AlertDialog.Builder(a).setTitle("Seu tempo").setItems(new String[]{"Temporizador para dormir","Modo de foco","Preferências de tempo e gestos"},(d,i)->{if(i==0)a.complete.sleepTimer();if(i==1)a.complete.focus(true);if(i==2)a.libraryHub.viewingSettings();}).show();if(n==5)new AlertDialog.Builder(a).setTitle("Assistir em outro lugar").setItems(new String[]{"Televisão","Janela flutuante","Baixar episódio"},(d,i)->{if(i==0)a.casting.show();if(i==1)a.playerExtras.pip();if(i==2)a.playerExtras.download(a.drama.episode);}).show();}).show();}
}
